const ip = $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const month = new Date().toISOString().slice(0, 7);
const key = 'rl_rakip_' + ip + '_' + month;
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
const cutoff = Date.now() - 62*24*60*60*1000;
Object.keys(staticData.rateLimits).forEach(k => { if ((staticData.rateLimits[k].ts||0) < cutoff) delete staticData.rateLimits[k]; });
const entry = staticData.rateLimits[key] || { count: 0, ts: Date.now() };
if (entry.count >= 50) {
  return [{ json: { rateLimitExceeded: true } }];
}
entry.count += 1;
entry.ts = Date.now();
staticData.rateLimits[key] = entry;
const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, prompt: body.prompt, competitors: body.competitors || [] } }];

// Gemini Flash'a gönderilecek arama isteğini hazırlar.
// Orijinal prompt ve competitors'ı static data'ya kaydeder — Gemini
// hata alsa bile Build MiniMax Body bunlara erişebilir.
const data = $input.first().json;
const competitors = data.competitors || [];

// Static data'ya kaydet (cross-node ref yerine güvenilir paylaşım)
const sd = $getWorkflowStaticData('global');
sd._rakipPrompt = data.prompt;
sd._rakipCompetitors = JSON.stringify(competitors);

if (!competitors.length) {
  return [{ json: { geminiSkipped: true } }];
}
const compList = competitors.map((c, i) => (i+1) + '. İşletme adı: ' + c.name + (c.web ? ', web sitesi: ' + c.web : '')).join('\n');
const geminiPrompt = 'GÖREV: Aşağıdaki her işletme için Google\'da arama yap ve resmi sosyal medya profil URL\'lerini bul.\n\nARANACAK İŞLETMELER:\n' + compList + '\n\nHer işletme için şu platformlarda resmi hesap URL\'si ara: Instagram, Facebook, LinkedIn, Google Business, WhatsApp.\nBulamazsan o alan için null yaz.\n\nYANIT FORMATI — SADECE BU JSON\'U DÖNDÜR, BAŞKA HİÇBİR AÇIKLAMA EKLEME:\n{"competitors":[{"name":"işletme adı","instagram":"https://... veya null","facebook":"https://... veya null","linkedin":"https://... veya null","google_business":"https://... veya null","whatsapp":"numara veya null"}]}';
const geminiBody = {
  contents: [{ parts: [{ text: geminiPrompt }] }],
  tools: [{ google_search: {} }]
};
return [{ json: { geminiBody } }];

const sd = $getWorkflowStaticData('global');
const originalPrompt = sd._rakipPrompt || '';

// Gemini çıktısını parse et ve platform verisini sakla
let platformReplacement = '';
let geminiPlatforms = []; // HTML tabloya gidecek
try {
  const geminiRaw = $input.first().json;
  const parts = geminiRaw.candidates?.[0]?.content?.parts || [];
  const geminiText = parts.map(p => p.text || '').join('');
  const jsonStart = geminiText.indexOf('{');
  const jsonEnd = geminiText.lastIndexOf('}');
  if (jsonStart !== -1 && jsonEnd !== -1) {
    const parsed = JSON.parse(geminiText.slice(jsonStart, jsonEnd + 1));
    if (parsed.competitors?.length) {
      geminiPlatforms = parsed.competitors;
      let info = '\n\u2550\u2550\u2550 GEM\u0130N\u0130 ARA\u015eTIRMA SONUÇLARI (ger\u00e7ek zamanl\u0131 web aramas\u0131) \u2550\u2550\u2550\n';
      info += parsed.competitors.map(c => {
        const found = [
          c.instagram && c.instagram !== 'null' ? 'Instagram: ' + c.instagram : null,
          c.facebook && c.facebook !== 'null' ? 'Facebook: ' + c.facebook : null,
          c.linkedin && c.linkedin !== 'null' ? 'LinkedIn: ' + c.linkedin : null,
          c.google_business && c.google_business !== 'null' ? 'Google Business: ' + c.google_business : null,
          c.whatsapp && c.whatsapp !== 'null' ? 'WhatsApp: ' + c.whatsapp : null,
        ].filter(Boolean);
        return c.name + ': ' + (found.length ? found.join(' | ') : 'platform bulunamad\u0131');
      }).join('\n');
      platformReplacement = info;
    }
  }
} catch(e) {}

const fallback = '(Rakibin b\u00fcy\u00fckl\u00fc\u011f\u00fcne ve sekt\u00f6r\u00fcne g\u00f6re hangi platformlarda aktif oldu\u011funu uzmanl\u0131\u011f\u0131nla tahmin et, her rakip i\u00e7in platform listesini analize dahil et.)';
const enrichedPrompt = originalPrompt.replace(
  '(Gemini AI taraf\u0131ndan ara\u015ft\u0131r\u0131lacak)',
  platformReplacement || fallback
);

const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 12000,
  messages: [{ role: 'user', content: enrichedPrompt }]
};
return [{ json: { apiBody, geminiPlatforms } }];

const data = $input.first().json;
let text = data.choices?.[0]?.message?.content || '';
const thinkEnd = text.lastIndexOf('</think>');
if (thinkEnd !== -1) text = text.slice(thinkEnd + '</think>'.length);
const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);
// Çince karakter kalıntısı varsa temizle (MiniMax-M3 bazen think'te Çince bırakır)
text = text.replace(/[\u4e00-\u9fff\u3400-\u4dbf]/g, '');
// geminiPlatforms'u Build MiniMax Body'den al
const geminiPlatforms = $('Build MiniMax Body').item.json.geminiPlatforms || [];
return [{ json: { content: [{ type: 'text', text }], geminiPlatforms } }];
